class TicTacToe {
  // +1 for player 1, -1 for player 2; a line wins when its total reaches +-n
  private final int[] rows, cols;
  private int diag, anti;
  private final int n;

  public TicTacToe(int n) {
    this.n = n;
    rows = new int[n];
    cols = new int[n];
  }

  public int move(int row, int col, int player) {
    int v = player == 1 ? 1 : -1;
    rows[row] += v;
    cols[col] += v;
    if (row == col) diag += v;
    if (row + col == n - 1) anti += v;
    if (Math.abs(rows[row]) == n || Math.abs(cols[col]) == n || Math.abs(diag) == n || Math.abs(anti) == n) return player;
    return 0;
  }
}
